parameters.jsCode:
// 1. Capturamos el texto crudo que viene de la IA (manejando variantes comunes de campos)
const textFromAI = $input.item.json.output || $input.item.json.text || "";

try {
  // 2. Implementación de Regex para capturar todo lo que esté entre { y }
  const jsonRegex = /\{[\s\S]*\}/;
  const match = textFromAI.match(jsonRegex);

  if (match) {
    // Extraemos el string JSON puro y lo parseamos a un objeto real
    const parsedData = JSON.parse(match[0]);

    // 3. Mapeo Dinámico: Entregamos la data estructurada dentro de 'output_limpio'
    return [{
      json: {
        output_limpio: {
          classification: parsedData.classification || parsedData.output?.classification || "Low Value",
          reason: parsedData.reason || parsedData.output?.reason || "No se especificó la razón."
        }
      }
    }];
  } else {
    throw new Error("No se detectaron llaves JSON en la respuesta de la IA.");
  }
} catch (error) {
  // Bloque de contingencia ultra-seguro para producción si la IA colapsa
  return [{
    json: {
      output_limpio: {
        classification: "Low Value",
        reason: "Error de parseo corregido automáticamente por el sistema: " + error.message
      }
    }
  }];
}

